1import { useState, useEffect } from "react";
2import Header from "./components/Header";
3import EntryCard from "./components/EntryCard";
4import Drawer from "./components/Drawer";
5
6function App() {
7  const [entries, setEntries] = useState([]);
8  const [isLoading, setIsLoading] = useState(true);
9  const [error, setError] = useState(null);
10  const [refreshKey, setRefreshKey] = useState(0);
11  const [selectedEntry, setSelectedEntry] = useState(null);
12
13  useEffect(function () {
14    async function loadEntries() {
15      setIsLoading(true);
16      setError(null);
17      try {
18        const res = await fetch("https://api.programiz.pro/api/Demo/v1/journal-entries");
19        if (!res.ok) {
20          throw new Error("Could not load entries. Status: " + res.status);
21        }
22        const data = await res.json();
23        const mapped = data.map((post) => {
24          return {
25            ...post,
26            date: new Date(post.date).toLocaleDateString("en-US", {
27              year: "numeric", month: "short", day: "numeric"
28            }).toUpperCase()
29          };
30        });
31        setEntries(mapped);
32        setIsLoading(false);
33      } catch (err) {
34        setError(err.message);
35        setIsLoading(false);
36      }
37    }
38    loadEntries();
39  }, [refreshKey]);
40
41  function handleSelectEntry(entry) {
42    setSelectedEntry(entry);
43  }
44
45  return (
46    <div className="main-container">
47      <Header />
48      <section className="entries-section">
49        <div className="entry-list-header">
50          <h3>Recent Entries</h3>
51          <span className="entry-count">{entries.length}</span>
52          <button
53            className="btn btn-secondary"
54            onClick={() => setRefreshKey((k) => k + 1)}
55          >
56            Refresh
57          </button>
58        </div>
59        {isLoading ? (
60          <p className="loading-state">Loading entries...</p>
61        ) : error ? (
62          <div className="error-banner">
63            <p className="error-label">Something went wrong.</p>
64            <p className="error-detail">{error}</p>
65          </div>
66        ) : entries.length === 0 ? (
67          <p className="empty-state">No entries found.</p>
68        ) : (
69          entries.map((entry) => (
70            <EntryCard
71              key={entry.id}
72              id={entry.id}
73              title={entry.title}
74              date={entry.date}
75              content={entry.content}
76              author={entry.author}
77              onSelect={handleSelectEntry}
78            />
79          ))
80        )}
81      </section>
82      <Drawer
83        entry={selectedEntry}
84        onClose={() => setSelectedEntry(null)}
85      />
86    </div>
87  );
88}
89
90export default App;

